1091	def emit_javascript(cases: list[TestCase], entrypoint: str) -> str:
1092	    cases_json = json.dumps(
1093	        [{"id": tc.id, "kind": tc.kind,
1094	          "args": _to_json_value(tc.args), "expected": _to_json_value(tc.expected),
1095	          "expectStdout": tc.expect_stdout, "expectStderr": tc.expect_stderr,
1096	          "tolAbs": tc.tol_abs, "tolRel": tc.tol_rel, "tolStrict": tc.tol_strict,
1097	          "excType": tc.exc_type, "msgContains": tc.msg_contains, "msgRegex": tc.msg_regex,
1098	          "transform": tc.transform, "mutationCheck": tc.mutation_check}
1099	         for tc in cases],
1100	        indent=2,
1101	    )
1102	    ep_json = json.dumps(entrypoint)
1103	
1104	    return f"""\
1105	'use strict';
1106	const fs = require('fs');
1107	const path = require('path');
1108	
1109	const ENTRYPOINT = {ep_json};
1110	const CASES = {cases_json};
1111	
1112	function decode(v) {{
1113	  if (Array.isArray(v)) return v.map(decode);
1114	  if (v !== null && typeof v === 'object' && v.__type__) {{
1115	    const t = v.__type__;
1116	    if (t === 'tuple' || t === 'deque') return v.value.map(decode);
1117	    if (t === 'set' || t === 'frozenset') return {{ __isSet: true, items: v.value.map(decode) }};
1118	    if (t === 'dict') {{
1119	      const o = {{}};
1120	      for (let i = 0; i < v.keys.length; i++) o[JSON.stringify(decode(v.keys[i]))] = {{ k: decode(v.keys[i]), v: decode(v.values[i]) }};
1121	      return {{ __isDict: true, entries: o }};
1122	    }}
1123	    if (t === 'counter' || t === 'defaultdict') return decode(v.value);
1124	    if (t === 'decimal') return parseFloat(v.value);
1125	    return v;
1126	  }}
1127	  return v;
1128	}}
1129	
1130	const _TRANSFORMS = {{
1131	  sorted: v => {{ const a = Array.isArray(v) ? [...v] : Array.from(v); return a.sort((a, b) => typeof a === 'number' ? a - b : String(a) < String(b) ? -1 : 1); }},
1132	  len: v => Array.isArray(v) ? v.length : (typeof v === 'string' ? v.length : Object.keys(v).length),
1133	  list: v => Array.isArray(v) ? [...v] : Array.from(v),
1134	  set: v => ({{ __isSet: true, items: [...new Set(v)] }}),
1135	  tuple: v => Array.isArray(v) ? [...v] : Array.from(v),
1136	  str: v => String(v),
1137	  int: v => Math.trunc(Number(v)),
1138	  float: v => Number(v),
1139	  abs: v => Math.abs(v),
1140	  sum: v => v.reduce((a, b) => a + b, 0),
1141	  min: v => Math.min(...v),
1142	  max: v => Math.max(...v),
1143	}};
1144	
1145	function setEq(a, b) {{
1146	  if (a.items.length !== b.items.length) return false;
1147	  return a.items.every(x => b.items.some(y => deepEq(x, y)));
1148	}}
1149	
1150	function dictEq(a, b) {{
1151	  const ka = Object.keys(a.entries).sort(), kb = Object.keys(b.entries).sort();
1152	  if (ka.join('\\0') !== kb.join('\\0')) return false;
1153	  return ka.every(k => deepEq(a.entries[k].v, b.entries[k].v));
1154	}}
1155	
1156	function near(a, b, tolAbs, tolRel, strict) {{
1157	  if (typeof a !== 'number' || typeof b !== 'number') return false;
1158	  const diff = Math.abs(a - b);
1159	  let limit = tolAbs !== null ? tolAbs : 0;
1160	  if (tolRel !== null) limit = Math.max(limit, tolRel * Math.max(Math.abs(a), Math.abs(b)));
1161	  return strict ? diff < limit : diff <= limit;
1162	}}
1163	
1164	function deepEq(a, b, tolAbs, tolRel, strict) {{
1165	  if (tolAbs !== undefined && tolAbs !== null && typeof a === 'number' && typeof b === 'number') {{
1166	    return near(a, b, tolAbs, tolRel !== undefined ? tolRel : null, strict !== undefined ? strict : true);
1167	  }}
1168	  if (a && a.__isSet && b && b.__isSet) return setEq(a, b);
1169	  if (a && a.__isDict && b && b.__isDict) return dictEq(a, b);
1170	  if (Array.isArray(a) && Array.isArray(b)) {{
1171	    return a.length === b.length && a.every((x, i) => deepEq(x, b[i], tolAbs, tolRel, strict));
1172	  }}
1173	  if (a !== null && b !== null && typeof a === 'object' && !Array.isArray(a) &&
1174	      typeof b === 'object' && !Array.isArray(b)) {{
1175	    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
1176	    return ka.join('\\0') === kb.join('\\0') && ka.every(k => deepEq(a[k], b[k], tolAbs, tolRel, strict));
1177	  }}
1178	  return a === b;
1179	}}
1180	
1181	function loadFn(sol, name) {{
1182	  if (sol && typeof sol[name] === 'function') {{
1183	    try {{
1184	      const inst = new sol[name]();
1185	      if (typeof inst[name] === 'function') return (...a) => inst[name](...a);
1186	    }} catch (e) {{}}
1187	    return (...a) => sol[name](...a);
1188	  }}
1189	  if (typeof sol === 'function') return (...a) => sol(...a);
1190	  throw new Error('Cannot resolve entrypoint: ' + name);
1191	}}
1192	
1193	function captureCall(fn, args) {{
1194	  let stdout = '', stderr = '';
1195	  const ow = process.stdout.write.bind(process.stdout);
1196	  const ew = process.stderr.write.bind(process.stderr);
1197	  process.stdout.write = c => {{ stdout += c; return true; }};
1198	  process.stderr.write = c => {{ stderr += c; return true; }};
1199	  let result, threw = false, thrownErr = null;
1200	  try {{ result = fn(...args); }} catch (e) {{ threw = true; thrownErr = e; }}
1201	  finally {{ process.stdout.write = ow; process.stderr.write = ew; }}
1202	  return {{ result, stdout, stderr, threw, thrownErr }};
1203	}}
1204	
1205	function run() {{
1206	  const solPath = process.argv[2];
1207	  const resultsPath = process.env._BCG_RESULTS_FILE;
1208	  const globalTol = process.env._BCG_TOL !== undefined ? parseFloat(process.env._BCG_TOL) : null;
1209	  const allIds = CASES.map(c => c.id);
1210	  let fn;
1211	  try {{
1212	    const sol = require(path.resolve(solPath));
1213	    fn = loadFn(sol, ENTRYPOINT);
1214	  }} catch (e) {{
1215	    fs.writeFileSync(resultsPath, JSON.stringify({{passed: [], failed: allIds}}));
1216	    return;
1217	  }}
1218	  const passed = [], failed = [];
1219	  for (const c of CASES) {{
1220	    if (c.kind === 'loop_pass') {{ passed.push(c.id); continue; }}
1221	    if (c.kind === 'loop_fail') {{ failed.push(c.id); continue; }}
1222	    const args = c.args.map(decode);
1223	    const expected = decode(c.expected);
1224	    const tolAbs = c.tolAbs !== null ? c.tolAbs : globalTol;
1225	    const tolRel = c.tolRel;
1226	    const tolStrict = c.tolStrict;
1227	    try {{
1228	      if (c.kind === 'raises') {{
1229	        let thrownErr = null;
1230	        try {{ fn(...args); }} catch (e) {{ thrownErr = e; }}
1231	        if (thrownErr === null) {{ failed.push(c.id); continue; }}
1232	        let ok = true;
1233	        if (c.excType !== null) ok = (thrownErr && thrownErr.constructor && thrownErr.constructor.name === c.excType) || (thrownErr && thrownErr.name === c.excType);
1234	        if (ok && c.msgContains !== null) ok = String(thrownErr && thrownErr.message || thrownErr).includes(c.msgContains);
1235	        if (ok && c.msgRegex !== null) ok = new RegExp(c.msgRegex).test(String(thrownErr && thrownErr.message || thrownErr));
1236	        (ok ? passed : failed).push(c.id);
1237	        continue;
1238	      }}
1239	      const mutationCheck = c.mutationCheck;
1240	      const {{ result: _raw, stdout, stderr, threw }} = captureCall(fn, args);
1241	      if (threw) {{ failed.push(c.id); continue; }}
1242	      const _result = mutationCheck !== null ? args[mutationCheck] : _raw;
1243	      const result = c.transform !== null ? _TRANSFORMS[c.transform](_result) : _result;
1244	      let ok = true;
1245	      if (c.kind === 'eq') ok = deepEq(result, expected, tolAbs, tolRel, tolStrict);
