def _cpp_compile(tester: Path, sol: Path, out: Path) -> int:
    try:
        result = subprocess.run(
            ["g++", "-std=c++17", f"-include{sol}", str(tester), "-o", str(out)],
            capture_output=True,
        )
        if result.returncode != 0:
